function validate([root, queries]) {
  if (!Array.isArray(root) || root[0] === null || root[0] === undefined) return 'The tree needs a root.';
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'The tree list has more entries than open child positions.';
    if (root[i] !== null) slots += 2;
  }
  const values = root.filter(v => v !== null);
  const n = values.length;
  if (n < 2 || n > 100000) return 'The tree has 2 to 100000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Node values run from 1 to the number of nodes.';
  if (new Set(values).size !== n) return 'Node values must be distinct.';
  if (queries.length < 1 || queries.length > Math.min(n, 10000)) return 'queries needs between 1 and min(n, 10000) values.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > n)) return 'Each query is a node value from 1 to n.';
  if (queries.includes(root[0])) return 'A query cannot remove the root.';
  return null;
}

