function treeQueries(root, queries) {
  const height = new Map();
  const measure = (node) => {
    if (!node) return -1;
    const h = 1 + Math.max(measure(node.left), measure(node.right));
    height.set(node.val, h);
    return h;
  };
  measure(root);

  const answer = new Map();
  const visit = (node, depth, restHeight) => {
    if (!node) return;
    answer.set(node.val, restHeight);
    const leftHeight = node.left ? height.get(node.left.val) : -1;
    const rightHeight = node.right ? height.get(node.right.val) : -1;
    visit(node.left, depth + 1, Math.max(restHeight, depth + 1 + rightHeight));
    visit(node.right, depth + 1, Math.max(restHeight, depth + 1 + leftHeight));
  };
  visit(root, 0, 0);

  return queries.map((value) => answer.get(value));
}

