function treeQueries(root, queries) {
  // For every query, walk the whole tree level by level while skipping the removed node.
  return queries.map((removed) => {
    let level = [root];
    let deepest = -1;
    while (level.length) {
      deepest++;
      const next = [];
      for (const node of level) {
        for (const child of [node.left, node.right]) {
          if (child && child.val !== removed) next.push(child);
        }
      }
      level = next;
    }
    return deepest;
  });
}

