function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 2 + Math.floor(rand() * 9);
  // Node values are a shuffled 1..n.
  const values = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  // Some trees begin with a long chain so that one deep branch dominates the height.
  const chain = large ? (rand() < 0.5 ? 50 + Math.floor(rand() * 400) : 1) : (rand() < 0.3 ? 1 + Math.floor(rand() * n) : 1);
  const nodes = [{ val: values[0], left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: values[i], left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = 0; i < chain - 1; i++) slots.push([i, nodes[i].left === null ? 'left' : 'right']);
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: values[i], left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const tree = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { tree.push(null); continue; }
    const node = nodes[queue[q]];
    tree.push(node.val);
    queue.push(node.left, node.right);
  }
  while (tree[tree.length - 1] === null) tree.pop();
  const m = large ? 300 + Math.floor(rand() * (n - 300)) : 1 + Math.floor(rand() * n);
  const queries = Array.from({ length: m }, () => values[1 + Math.floor(rand() * (n - 1))]);
  return [tree, queries];
}
